/**
 * The contract `checkbox.tsx` (native) and `checkbox.web.tsx` (radix) both implement. Its own
 * module because Metro resolves `./checkbox` to `checkbox.web.tsx` on web — the web file would
 * otherwise import itself.
 *
 * Controlled or not, as radix's is: pass `checked` and `onCheckedChange` to drive it, or
 * `defaultChecked` (or nothing) and let it hold its own state. The web half takes radix's whole
 * `Checkbox.Root` surface on top of this — `name`, `value`, `required`, `id`, `"indeterminate"`,
 * the `aria-*` props — because it installs over a DOM app's shadcn checkbox; this is the part that
 * means something on both platforms.
 */
export type CheckboxProps = {
  checked?: boolean | undefined;
  /** Where an uncontrolled box starts. Ignored once `checked` is passed. */
  defaultChecked?: boolean | undefined;
  onCheckedChange?: ((checked: boolean) => void) | undefined;
  disabled?: boolean | undefined;
  /**
   * Fired when the control loses focus. A bound field marks itself touched from
   * this, which is what decides whether an error is shown yet — so a checkbox
   * without one is a required field that never reports itself as unfilled.
   */
  onBlur?: (() => void) | undefined;
  /**
   * Required on device: the box carries no visible label of its own, and there is no
   * `<label htmlFor>` to borrow one from. (On web a `<Label htmlFor={id}>` or an `aria-label` does
   * it, so the web half does not ask for this — but takes it, as the box's `aria-label`, so a call
   * site shared across both halves is named on both.)
   */
  accessibilityLabel: string;
  /**
   * The value was refused: a validator's error. The edge turns `negative`, over the `active` edge
   * of a checked one, so a required box that is wrong says so whichever state it is in. A bound
   * field sets it; the web half takes it as radix's attribute.
   */
  "aria-invalid"?: boolean | "true" | "false" | undefined;
  className?: string | undefined;
};

/**
 * The box, shared so the two halves cannot drift apart visually.
 *
 * @border-colour each half adds it beside this, from the checked state.
 */
export const CHECKBOX_CLASS = "h-4 w-4 shrink-0 items-center justify-center rounded-sm border";

/**
 * The native checkbox, built from a `Pressable`. `checkbox.web.tsx` is radix's, and
 * `checkbox-base.ts` holds the contract they share.
 *
 * `role="checkbox"` plus `aria-checked` is what makes it a real checkbox to a
 * screen reader; the role and `aria-checked` below are the part that actually
 * matters, and they cost nothing.
 */

import { useState } from "react";
import { Platform, Pressable } from "react-native";
import { CHECKBOX_CLASS, type CheckboxProps } from "@/components/ui/checkbox-base";
import { Check } from "@/components/ui/icons";
import { cn, isInvalid } from "@/lib/utils";

/** A box that is checked or not. */
function Checkbox({
  checked: checkedProp,
  defaultChecked = false,
  onCheckedChange,
  disabled = false,
  onBlur,
  accessibilityLabel,
  "aria-invalid": ariaInvalid,
  className,
}: CheckboxProps) {
  // Controlled when `checked` is passed and self-driving otherwise, the way radix's is.
  const [checkedState, setCheckedState] = useState(defaultChecked);
  const checked = checkedProp ?? checkedState;
  return (
    <Pressable
      role="checkbox"
      aria-checked={checked}
      aria-label={accessibilityLabel}
      // What react-native has no prop for, in the spelling react-native-web reads, as `Input` does.
      {...(Platform.OS === "web" && ariaInvalid !== undefined
        ? { "aria-invalid": ariaInvalid }
        : {})}
      disabled={disabled}
      onPress={() => {
        setCheckedState(!checked);
        onCheckedChange?.(!checked);
      }}
      onBlur={onBlur}
      className={cn(
        CHECKBOX_CLASS,
        // Checked is the chosen tint, edged in `active` because the tint is not 3:1 from the
        // surface; the check is `foreground`, 3:1 or more on the tint and around it. Focused, a box
        // looks as it does under the pointer, for Expo web, and draws no ring.
        "focus-visible:outline-none",
        checked
          ? "border-active bg-active/40 hover:bg-active/60 focus-visible:bg-active/60"
          : "border-foreground/50 bg-background hover:bg-hover focus-visible:bg-hover",
        // After the checked edge, so a refused box is red whether it is checked or not.
        isInvalid(ariaInvalid) && "border-negative",
        disabled && "opacity-50",
        className,
      )}
    >
      {checked && <Check className="h-3 w-3 text-foreground" />}
    </Pressable>
  );
}

export type { CheckboxProps };
export { Checkbox };

/**
 * The web checkbox: radix. `checkbox.tsx` is the native counterpart and `checkbox-base.ts` holds
 * the contract they share.
 *
 * It used to be compiled from the native `Pressable`, which made it a `<button role="checkbox">`
 * with a required `aria-label` and nothing else — no `name`, no `value`, no `required`, nothing a
 * `<form>` submit could see, and no uncontrolled use. This file installs over a DOM app's shadcn
 * checkbox at `components/ui/checkbox.tsx`, so it takes radix's `Checkbox.Root` props whole, as
 * shadcn's does: radix renders the hidden `<input>` a native form submit reads, and a
 * `<Label htmlFor={id}>` names it.
 */

import { Checkbox as CheckboxPrimitive } from "radix-ui";
import type { ComponentPropsWithRef } from "react";
import { CHECKBOX_CLASS } from "@/components/ui/checkbox-base";
import { Check } from "@/components/ui/icons";
import { cn } from "@/lib/utils";

/**
 * radix's props, with `className` re-declared for `exactOptionalPropertyTypes`. Every prop of the
 * shared contract but `accessibilityLabel` is already one of radix's; a `() => void` is a DOM
 * `onBlur`.
 */
export type CheckboxProps = Omit<
  ComponentPropsWithRef<typeof CheckboxPrimitive.Root>,
  "className"
> & {
  className?: string | undefined;
  /**
   * The device half's name for the box, taken here so a call site shared across both halves —
   * typechecked against the device half, so this is all it passes — still names it. It becomes
   * `aria-label`; an `aria-label` of its own wins. Optional, because on the web a
   * `<Label htmlFor={id}>` can name the box instead.
   */
  accessibilityLabel?: string | undefined;
};

/** A box that is checked, unchecked or indeterminate. */
function Checkbox({
  className,
  accessibilityLabel,
  "aria-label": ariaLabel,
  ...props
}: CheckboxProps) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      {...props}
      aria-label={ariaLabel ?? accessibilityLabel}
      className={cn(
        CHECKBOX_CLASS,
        // Invalid is stacked on the checked states, not only beside them: a `data-[state]:` edge is
        // emitted after an `aria-invalid:` one and would win, hiding a refused checked box.
        "peer flex border-foreground/50 bg-background text-foreground focus-visible:outline-none data-[state=unchecked]:hover:bg-hover data-[state=unchecked]:focus-visible:bg-hover disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-negative aria-invalid:data-[state=checked]:border-negative aria-invalid:data-[state=indeterminate]:border-negative data-[state=checked]:border-active data-[state=checked]:bg-active/40 data-[state=checked]:hover:bg-active/60 data-[state=checked]:focus-visible:bg-active/60 data-[state=indeterminate]:border-active data-[state=indeterminate]:bg-active/40 data-[state=indeterminate]:hover:bg-active/60 data-[state=indeterminate]:focus-visible:bg-active/60",
        className,
      )}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="flex items-center justify-center text-current"
      >
        <Check className="h-3 w-3" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}

export { Checkbox };
